-- Loads the conflicts and gaps found while reconciling every source document into the
-- To Validate queue (kb_review_queue). Run it once in the Supabase SQL Editor, after supabase.sql.
-- Safe to run again: an item already in the queue is not added twice, and if an earlier version of
-- the same topic is still pending (from a previous run of this file), it is rejected and replaced.

update kb_review_queue set status = 'rejected', resolved_at = now()
where submitted_by = 'source reconciliation' and status = 'pending'
  and raw_input like $q$[Warranty start date and length]%$q$ and raw_input <> $q$[Warranty start date and length] Warranty Conditions document (all MYKA and theo grace sites): warranty starts from the ETA, 2 years for all products since January 22nd 2023, extended only on the first and only reorder, from the new ETA. Still saying otherwise: the Item Received policy export (out of warranty instructions count from the delivery date), the add-on warranty pack macros (2 years from the purchase date), and a marketplace macro that says '1-year warranty'.$q$;
insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$The 2 year warranty is counted from the ETA, for every material since January 22nd 2023 (Warranty Conditions document). The delivery date, purchase date and 1 year wordings are outdated.$q$, $q$[Warranty start date and length] Warranty Conditions document (all MYKA and theo grace sites): warranty starts from the ETA, 2 years for all products since January 22nd 2023, extended only on the first and only reorder, from the new ETA. Still saying otherwise: the Item Received policy export (out of warranty instructions count from the delivery date), the add-on warranty pack macros (2 years from the purchase date), and a marketplace macro that says '1-year warranty'.$q$, $q$The new document is explicit about the ETA and the 2 years, so this only needs a confirmation that the older wordings (delivery date, purchase date, 1 year) are outdated and should be corrected in the Notch configuration and the macros.$q$, $q$Item Received configuration and macros that count from the delivery or purchase date, or mention 1 year.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Warranty start date and length] Warranty Conditions document (all MYKA and theo grace sites): warranty starts from the ETA, 2 years for all products since January 22nd 2023, extended only on the first and only reorder, from the new ETA. Still saying otherwise: the Item Received policy export (out of warranty instructions count from the delivery date), the add-on warranty pack macros (2 years from the purchase date), and a marketplace macro that says '1-year warranty'.$q$);

update kb_review_queue set status = 'rejected', resolved_at = now()
where submitted_by = 'source reconciliation' and status = 'pending'
  and raw_input like $q$[Solid gold purities offered]%$q$ and raw_input <> $q$[Solid gold purities offered] Materials FAQ: solid gold 10k, 14k and 18k. Approved vermeil answer from real tickets: solid gold 10K and 14K, gold plated and vermeil 18K. Premium definition in the Damaged policy: 10K, 14K or 18K solid gold. Marketplace macro: solid gold 10k or 14k. Care macro: solid gold purity 9k, 10k and 14k.$q$;
insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Solid gold is offered in 10K, 14K and 18K (confirm per brand), gold plated and vermeil are 18K gold.$q$, $q$[Solid gold purities offered] Materials FAQ: solid gold 10k, 14k and 18k. Approved vermeil answer from real tickets: solid gold 10K and 14K, gold plated and vermeil 18K. Premium definition in the Damaged policy: 10K, 14K or 18K solid gold. Marketplace macro: solid gold 10k or 14k. Care macro: solid gold purity 9k, 10k and 14k.$q$, $q$The knowledge base itself contains two contradicting statements (one lists 18K solid gold, the other says solid gold is only 10K and 14K), and two macros give other lists. A customer asking about purity gets different answers.$q$, $q$Common facts: 'solid gold in 10k, 14k, and 18k' versus 'solid gold pieces are offered in 10K and 14K'.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Solid gold purities offered] Materials FAQ: solid gold 10k, 14k and 18k. Approved vermeil answer from real tickets: solid gold 10K and 14K, gold plated and vermeil 18K. Premium definition in the Damaged policy: 10K, 14K or 18K solid gold. Marketplace macro: solid gold 10k or 14k. Care macro: solid gold purity 9k, 10k and 14k.$q$);

update kb_review_queue set status = 'rejected', resolved_at = now()
where submitted_by = 'source reconciliation' and status = 'pending'
  and raw_input like $q$[Water resistance, all pieces or only badged ones]%$q$ and raw_input <> $q$[Water resistance, all pieces or only badged ones] Water macro: 'All of our jewelry pieces are water resistant', remove silver, gold plated and vermeil in the shower because soapy water dulls them. Newer theo grace instruction: only products with the blue Water Resistant badge can be called water resistant, others follow the regular policy.$q$;
insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Water resistance can only be confirmed for products showing the Water Resistant badge (theo grace), otherwise give the general care guidance and avoid promising.$q$, $q$[Water resistance, all pieces or only badged ones] Water macro: 'All of our jewelry pieces are water resistant', remove silver, gold plated and vermeil in the shower because soapy water dulls them. Newer theo grace instruction: only products with the blue Water Resistant badge can be called water resistant, others follow the regular policy.$q$, $q$The macro states all pieces are water resistant, the new badge implies it is a per-product feature. The macro may predate the badge.$q$, $q$Common fact: jewelry is water resistant, not waterproof.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Water resistance, all pieces or only badged ones] Water macro: 'All of our jewelry pieces are water resistant', remove silver, gold plated and vermeil in the shower because soapy water dulls them. Newer theo grace instruction: only products with the blue Water Resistant badge can be called water resistant, others follow the regular policy.$q$);

update kb_review_queue set status = 'rejected', resolved_at = now()
where submitted_by = 'source reconciliation' and status = 'pending'
  and raw_input like $q$[Compensation on damaged items (coupon and exchange credit)]%$q$ and raw_input <> $q$[Compensation on damaged items (coupon and exchange credit)] Hub damaged policy and the Item Received export: reorder, exchange (customer pays or receives store credit for the price difference), store credit, refund only within 30 days. No coupon is mentioned. Macros (Arrived_Damaged, Damaged_Silver, Gold_Warranty, Silver_Warranty, Reorder_Before_Oct): a 30% coupon valid 6 months and 'pick any other piece with an extra $20 credit on us'.$q$;
insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$For a damaged item, follow the current policy: reorder, then exchange, then store credit, refund only on request. The 30% coupon and the extra $20 credit in the older macros are not offered unless a team lead confirms.$q$, $q$[Compensation on damaged items (coupon and exchange credit)] Hub damaged policy and the Item Received export: reorder, exchange (customer pays or receives store credit for the price difference), store credit, refund only within 30 days. No coupon is mentioned. Macros (Arrived_Damaged, Damaged_Silver, Gold_Warranty, Silver_Warranty, Reorder_Before_Oct): a 30% coupon valid 6 months and 'pick any other piece with an extra $20 credit on us'.$q$, $q$The macros add gestures (30% coupon, $20 credit) that the current policies never mention. Unclear whether they are still given.$q$, $q$Damaged rules in the knowledge base (marked as legacy macro extras to confirm).$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Compensation on damaged items (coupon and exchange credit)] Hub damaged policy and the Item Received export: reorder, exchange (customer pays or receives store credit for the price difference), store credit, refund only within 30 days. No coupon is mentioned. Macros (Arrived_Damaged, Damaged_Silver, Gold_Warranty, Silver_Warranty, Reorder_Before_Oct): a 30% coupon valid 6 months and 'pick any other piece with an extra $20 credit on us'.$q$);

