insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Late compensation is offered from the day after the ETA, the customer chooses from the late compensation options page.$q$, $q$[Late compensation, when it starts and what is offered] Late sub-policy document: offer late compensation when the customer asks a day after the promised date. Late_After_3_days macro: only send when more than 3 business days past the ETA. Amounts in macros: $15 gift card, 20% coupon, 30% coupon, shipping fee refund, 15% refund for USPS/Mailog almost lost cases. The actual options on the late compensation page are not documented anywhere.$q$, $q$Two different starting points (1 day versus 3 business days) and no definitive list of what the customer can choose.$q$, $q$Earlier knowledge base wording: no compensation for a delay under 3 business days.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Late compensation, when it starts and what is offered] Late sub-policy document: offer late compensation when the customer asks a day after the promised date. Late_After_3_days macro: only send when more than 3 business days past the ETA. Amounts in macros: $15 gift card, 20% coupon, 30% coupon, shipping fee refund, 15% refund for USPS/Mailog almost lost cases. The actual options on the late compensation page are not documented anywhere.$q$);

