insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$A free gift can be added to an order that used a coupon (Free Gift Eligibility policy), the one coupon, voucher or free gift per order statement applies to coupons and vouchers only.$q$, $q$[Free gift and the one coupon per order statement] Free Gift Eligibility document: a free gift is allowed on an order that used a coupon, eligible when the order was placed within 12 hours before to 72 hours after the campaign. Warranty and FAQ statements: only one coupon, voucher or free gift can be used per order.$q$, $q$The two statements can't both be true as worded.$q$, $q$Common fact: only one coupon, voucher, or free gift can be used per order.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Free gift and the one coupon per order statement] Free Gift Eligibility document: a free gift is allowed on an order that used a coupon, eligible when the order was placed within 12 hours before to 72 hours after the campaign. Warranty and FAQ statements: only one coupon, voucher or free gift can be used per order.$q$);

update kb_review_queue set status = 'rejected', resolved_at = now()
where submitted_by = 'source reconciliation' and status = 'pending'
  and raw_input like $q$[All methods tracked and insured versus non-tracked shipping]%$q$ and raw_input <> $q$[All methods tracked and insured versus non-tracked shipping] Site cart screenshots in the shipping information document: 'All methods are tracked & insured' with USPS, FedEx and DHL. WISMO policies: non-tracked shipping rules, and a non-trackable DHL Royal HU method delivered to theo grace UK.$q$;
insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Most shipping methods are tracked and insured, a few methods (for example DHL Royal HU for theo grace UK, and some non-tracked methods) are not.$q$, $q$[All methods tracked and insured versus non-tracked shipping] Site cart screenshots in the shipping information document: 'All methods are tracked & insured' with USPS, FedEx and DHL. WISMO policies: non-tracked shipping rules, and a non-trackable DHL Royal HU method delivered to theo grace UK.$q$, $q$The cart statement and the non-tracked rules contradict each other, so agents may tell a customer there is tracking when there isn't.$q$, $q$WISMO lost order and over 100 days rules (non-tracked shipping).$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[All methods tracked and insured versus non-tracked shipping] Site cart screenshots in the shipping information document: 'All methods are tracked & insured' with USPS, FedEx and DHL. WISMO policies: non-tracked shipping rules, and a non-trackable DHL Royal HU method delivered to theo grace UK.$q$);

update kb_review_queue set status = 'rejected', resolved_at = now()
where submitted_by = 'source reconciliation' and status = 'pending'
  and raw_input like $q$[Jewelry Protection Plan, benefits and price]%$q$ and raw_input <> $q$[Jewelry Protection Plan, benefits and price] Warranty Conditions document lists free returns, Refresh Your Style (2 years), Repair and Restore (5 years), Replacements (150 days) and 15% off the next purchase, with prices that differ between the US and Europe and by premium or non-premium. A site screenshot of the 5 year plan ($15) lists free returns, replacement of damaged jewelry (chain and clasp, missing stones, manufacturing issues) and free resizing, and does not mention Refresh Your Style or the 15% discount. Older macros mention an extended 2 year warranty.$q$;
insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Document the current Jewelry Protection Plan benefits and prices per site and per material.$q$, $q$[Jewelry Protection Plan, benefits and price] Warranty Conditions document lists free returns, Refresh Your Style (2 years), Repair and Restore (5 years), Replacements (150 days) and 15% off the next purchase, with prices that differ between the US and Europe and by premium or non-premium. A site screenshot of the 5 year plan ($15) lists free returns, replacement of damaged jewelry (chain and clasp, missing stones, manufacturing issues) and free resizing, and does not mention Refresh Your Style or the 15% discount. Older macros mention an extended 2 year warranty.$q$, $q$The benefits on the site don't match the policy document, and the exact prices aren't given.$q$, $q$Warranty conditions rule in the knowledge base.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Jewelry Protection Plan, benefits and price] Warranty Conditions document lists free returns, Refresh Your Style (2 years), Repair and Restore (5 years), Replacements (150 days) and 15% off the next purchase, with prices that differ between the US and Europe and by premium or non-premium. A site screenshot of the 5 year plan ($15) lists free returns, replacement of damaged jewelry (chain and clasp, missing stones, manufacturing issues) and free resizing, and does not mention Refresh Your Style or the 15% discount. Older macros mention an extended 2 year warranty.$q$);

update kb_review_queue set status = 'rejected', resolved_at = now()
where submitted_by = 'source reconciliation' and status = 'pending'
  and raw_input like $q$[Return label wording, UK processing and label generator]%$q$ and raw_input <> $q$[Return label wording, UK processing and label generator] Returning Order document: UK 'escalate only after the item is returned' but also 'QA will process the reorder or refund the moment the customer drops the return'. The label printing section is titled 'for SPING ONLY' then says the option is only available in Germany and France. Premium return instructions 'with PPE' isn't explained.$q$;
insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$UK: escalate only after the item is returned. The QR label generator is available in Germany and France only.$q$, $q$[Return label wording, UK processing and label generator] Returning Order document: UK 'escalate only after the item is returned' but also 'QA will process the reorder or refund the moment the customer drops the return'. The label printing section is titled 'for SPING ONLY' then says the option is only available in Germany and France. Premium return instructions 'with PPE' isn't explained.$q$, $q$Small inconsistencies in the document that change when a UK return is processed and which countries have the QR label option.$q$, $q$Customer returns and return logistics rule.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Return label wording, UK processing and label generator] Returning Order document: UK 'escalate only after the item is returned' but also 'QA will process the reorder or refund the moment the customer drops the return'. The label printing section is titled 'for SPING ONLY' then says the option is only available in Germany and France. Premium return instructions 'with PPE' isn't explained.$q$);
